import { test, expect } from '@playwright/test';

test.describe('Delete Account Feature', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login with test credentials
    await page.getByRole('link', { name: /login/i }).click();
    await page.getByLabel(/email/i).fill('testuser@example.com');
    await page.getByLabel(/password/i).fill('TestPassword123!');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for navigation to complete
    await page.waitForURL('/dashboard');
  });

  test('should display delete account option in user profile', async ({ page }) => {
    // Navigate to account settings
    await page.getByRole('button', { name: /account settings/i }).click();

    // Verify delete account section is visible
    const deleteAccountSection = page.getByRole('heading', { name: /delete account/i });
    await expect(deleteAccountSection).toBeVisible();

    // Verify delete button is present
    const deleteButton = page.getByRole('button', { name: /delete account/i });
    await expect(deleteButton).toBeVisible();
  });

  test('should show password confirmation dialog when delete account is clicked', async ({ page }) => {
    // Navigate to account settings
    await page.getByRole('button', { name: /account settings/i }).click();

    // Click delete account button
    await page.getByRole('button', { name: /delete account/i }).click();

    // Verify confirmation dialog appears
    const confirmationDialog = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmationDialog).toBeVisible();

    // Verify password input field is present
    const passwordInput = page.getByLabel(/confirm your password/i);
    await expect(passwordInput).toBeVisible();

    // Verify warning message is displayed
    const warningText = page.getByText(/this action cannot be undone/i);
    await expect(warningText).toBeVisible();
  });

  test('should successfully delete account with correct password', async ({ page }) => {
    // Navigate to account settings
    await page.getByRole('button', { name: /account settings/i }).click();

    // Click delete account button
    await page.getByRole('button', { name: /delete account/i }).click();

    // Wait for confirmation dialog
    const confirmationDialog = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmationDialog).toBeVisible();

    // Enter password
    await page.getByLabel(/confirm your password/i).fill('TestPassword123!');

    // Click confirm delete button
    await page.getByRole('button', { name: /confirm delete/i }).click();

    // Verify user is redirected to login page
    await page.waitForURL('/login');
    await expect(page).toHaveURL('/login');

    // Verify success message
    const successMessage = page.getByText(/account successfully deleted/i);
    await expect(successMessage).toBeVisible();
  });

  test('should show error when incorrect password is provided', async ({ page }) => {
    // Navigate to account settings
    await page.getByRole('button', { name: /account settings/i }).click();

    // Click delete account button
    await page.getByRole('button', { name: /delete account/i }).click();

    // Wait for confirmation dialog
    const confirmationDialog = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmationDialog).toBeVisible();

    // Enter incorrect password
    await page.getByLabel(/confirm your password/i).fill('WrongPassword123!');

    // Click confirm delete button
    await page.getByRole('button', { name: /confirm delete/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/incorrect password/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the same page
    await expect(confirmationDialog).toBeVisible();
  });

  test('should allow user to cancel account deletion', async ({ page }) => {
    // Navigate to account settings
    await page.getByRole('button', { name: /account settings/i }).click();

    // Click delete account button
    await page.getByRole('button', { name: /delete account/i }).click();

    // Wait for confirmation dialog
    const confirmationDialog = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmationDialog).toBeVisible();

    // Click cancel button
    await page.getByRole('button', { name: /cancel/i }).click();

    // Verify dialog is closed
    await expect(confirmationDialog).not.toBeVisible();

    // Verify user is still on account settings page
    const settingsHeading = page.getByRole('heading', { name: /account settings/i });
    await expect(settingsHeading).toBeVisible();
  });
});
